"use strict";
// Per-call micro-benchmarks, run from inside a package so the calls go through wrappers.
const os = require("os");
const fs = require("fs");

function time(n, fn) {
  for (let i = 0; i < Math.min(n, 10000); i++) fn(); // warm up
  const t0 = process.hrtime.bigint();
  for (let i = 0; i < n; i++) fn();
  return Number(process.hrtime.bigint() - t0) / n; // ns per op
}

module.exports = {
  // Pure wrapper cost: os.endianness() is a trivial JS function.
  endianness: (n) => time(n, () => os.endianness()),
  // A realistic syscall.
  statSync: (n, file) => time(n, () => fs.statSync(file)),
  // process.env reads: an ordinary key, and a credential-like key (stack-attributed).
  envRead: (n) => time(n, () => process.env.PATH),
  envSensitiveRead: (n) => time(n, () => process.env.SPIKE_TOKEN),
};
